import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.D90SBk1D.js";var i=JSON.parse(`{"title":"How it works","description":"","frontmatter":{},"headers":[],"relativePath":"guide/how-it-works.md","filePath":"guide/how-it-works.md","lastUpdated":1786917909000}`),a={name:`guide/how-it-works.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How it works”">​</a></h1><p>Two clocks. Almost every surprise in this library is mixing them up.</p><h2 id="mount-time" tabindex="-1">Mount time <a class="header-anchor" href="#mount-time" aria-label="Permalink to “Mount time”">​</a></h2><p><code>await admin.mount(app)</code> is async because this is when the schema is read.</p><ol><li><code>register(&quot;User&quot;)</code> only stored intent. It did not talk to Prisma.</li><li><code>mount</code> calls <code>getDMMF()</code> from <code>@prisma/internals</code> on your <code>schema.prisma</code>.</li><li>Every registered name is checked against the real models.</li><li>Field overrides, <code>listDisplay</code>, and <code>searchFields</code> are validated.</li><li>Missing config is filled from the schema (display field, columns, filters).</li><li>Express gets a router at <code>basePath</code> (default <code>/admin</code>): <ul><li><code>GET /admin/api/schema</code></li><li>CRUD and actions under <code>/admin/api/:model</code></li><li>the pre-built UI for every other path</li></ul></li></ol><p>If you <code>register(&quot;Users&quot;)</code> and the model is <code>User</code>, mount throws with the list of real names. Fail at boot, not on the first click.</p><p>That is why <code>mount</code> must be awaited, and why every <code>register</code> must happen <strong>before</strong> <code>mount</code>.</p><h2 id="request-time" tabindex="-1">Request time <a class="header-anchor" href="#request-time" aria-label="Permalink to “Request time”">​</a></h2><p>The browser loads one HTML page. React reads the URL. Data comes from the API. There is no new HTML document per screen.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET  /admin/api/schema</span></span>
<span class="line"><span>GET  /admin/api/users?page=1</span></span>
<span class="line"><span>GET  /admin/api/users/:id</span></span>
<span class="line"><span>POST /admin/api/users</span></span>
<span class="line"><span>PUT  /admin/api/users/:id</span></span>
<span class="line"><span>DELETE /admin/api/users/:id</span></span>
<span class="line"><span>POST /admin/api/users/actions/:action</span></span></code></pre></div><p>Every <code>/admin/api/*</code> call runs this pipeline:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>getCurrentUser → permission → scope → validate → Prisma → audit?</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Step</th><th>What it decides</th></tr></thead><tbody><tr><td><code>getCurrentUser</code></td><td>Who is this? <code>null</code> → 401</td></tr><tr><td>Permission</td><td>May this role list / view / create / update / delete / run the action?</td></tr><tr><td><code>scope()</code></td><td>Which rows? Combined with the id so guessing another tenant&#39;s id is 404</td></tr><tr><td>Validate</td><td>Only known, visible, writable fields. No nested writes.</td></tr><tr><td>Prisma</td><td><code>prisma.user.findMany</code> / <code>create</code> / <code>updateMany</code> / <code>deleteMany</code></td></tr><tr><td><code>audit.write</code></td><td>Optional. After success only. No field values.</td></tr></tbody></table><p>The UI never talks to Prisma. It fetches <code>/admin/api/schema</code> once and renders lists and forms from that JSON.</p><h2 id="why-admin-posts-123-still-works" tabindex="-1">Why <code>/admin/posts/123</code> still works <a class="header-anchor" href="#why-admin-posts-123-still-works" aria-label="Permalink to “Why /admin/posts/123 still works”">​</a></h2><p>There is no <code>posts/123.html</code>. Express serves <code>index.html</code> for any non-API path. React Router (basename <code>/admin</code>) shows the detail view. API routes are mounted first so they always win.</p><h2 id="what-the-schema-endpoint-is" tabindex="-1">What the schema endpoint is <a class="header-anchor" href="#what-the-schema-endpoint-is" aria-label="Permalink to “What the schema endpoint is”">​</a></h2><p><code>GET /admin/api/schema</code> is the brain of the UI. It returns registered models, visible fields, list columns, filters, and <strong>this admin&#39;s</strong> permissions as booleans.</p><p>It is behind the same auth middleware as CRUD. It exposes field names, enums, and relations. Do not serve it anonymously.</p><h2 id="the-type-the-rest-of-the-system-uses" tabindex="-1">The type the rest of the system uses <a class="header-anchor" href="#the-type-the-rest-of-the-system-uses" aria-label="Permalink to “The type the rest of the system uses”">​</a></h2><p>After mount, each model is a <code>FullRegisteredModel</code>:</p><ul><li><code>meta</code> — from DMMF (<code>User</code>, <code>users</code>, <code>prisma.user</code>, fields)</li><li><code>resolved</code> — defaults filled in (<code>listDisplay</code>, <code>perPage</code>, …)</li><li><code>raw</code> — your functions (<code>scope</code>, hooks, actions). Functions are not sent to the browser.</li></ul><p>The router reads all three. The UI only sees a JSON slice of <code>meta</code> + <code>resolved</code>.</p>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};